import{d as c,C as t,o as g,c as m,j as a,a as o,E as r,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二十八章","description":"从三组知守与复归，理解朴散为器及大制不割。","frontmatter":{"title":"道德经第二十八章","description":"从三组知守与复归，理解朴散为器及大制不割。","category":"guide","aliases":["道德经第二十八章","老子第二十八章","dao de jing chapter 28"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-28.md","filePath":"daoism/dao-de-jing/chapter-28.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-28.md"},k=c({...p,setup(b){const n=[{id:"knowing-the-male-keeping-the-female",label:"知其雄，守其雌，为天下溪",showLabel:!0,sentences:[[{text:"知",glossary:"zhi"},"其",{text:"雄",glossary:"xiong"},"，守其",{text:"雌",glossary:"ci"},"，为天下",{text:"溪",glossary:"xi"},"。"],["为天下溪，常德不离，复归于婴儿。"]],note:["【白话】知道雄强、在先的一面，仍守住柔和、居后的一面，成为天下汇流的溪谷。成为天下溪谷，常德便不离失，返归如婴儿般少机巧的状态。","【王弼注择要】「雄，先之属；雌，后之属也。」溪，注说「不求物而物自归之」；婴儿又以「不用智而合自然之智」解释。","【读法】本页循先后之注读雄雌，不据此规定现实男女的性格或地位。婴儿借少机巧、不先倡发说复归，不要求成人取消能力和责任。"]},{id:"knowing-white-keeping-black",label:"知其白，守其黑，为天下式",showLabel:!0,sentences:[["知其白，守其黑，为天下",{text:"式",glossary:"shi"},"。"],["为天下式，常德不",{text:"忒",glossary:"te"},"，复归于",{text:"无极",glossary:"wuji"},"。"]],note:["【白话】知道明白、显著的一面，仍守住幽隐、不自显的一面，成为天下的法式。成为天下法式，常德不差失，返归于无穷尽的境地。","【王弼注择要】「式，模则也。」忒，注释「忒，差也」；无极，注说「不可穷也」。三句强调可取法、不差失与不被穷尽。","【读法】白黑先保留明暗对举，再由整章守后、不自显的脉络理解；不是将事实上的黑白颠倒。无极在这里不直接等同后世宇宙图式中的专名。"]},{id:"knowing-honour-keeping-low",label:"知其荣，守其辱，为天下谷",showLabel:!0,sentences:[["知其",{text:"荣",glossary:"rong"},"，守其",{text:"辱",glossary:"ru"},"，为天下谷。"],["为天下谷，常德乃足，复归于",{text:"朴",glossary:"pu"},"。"]],note:["【白话】知道荣耀、显贵的一面，仍安守卑下、不逐荣的一面，成为天下的谷。成为天下之谷，常德才得充足，返归素朴本真。","【王弼注择要】「此三者，言常反终后，乃德全其所处也。」王弼将三组排句合说为返后而全德，并说「功不可取，常处其母也」。","【读法】辱在荣辱对照中取卑下、不受尊显的一面；不能据守辱要求别人忍受羞辱和侵害。朴在本章依王弼真义，不只停留在木材字面。"]},{id:"uncarved-whole-and-differentiated-tools",label:"朴散则为器，圣人用之",showLabel:!0,sentences:[["朴散则为",{text:"器",glossary:"qi"},"，圣人用之，则为",{text:"官长",glossary:"guanzhang"},"，故",{text:"大制",glossary:"dazhi"},"不割。"]],note:["【白话】朴散开便形成各有用途的器，圣人因其分殊而运用、设置官长，使各有所任；因此大的治理不割裂整体。这一段本页循王弼设官长的读法理解。","【王弼注择要】「朴，真也。」注从「真散则百行出，殊类生，若器也」说分殊，末尾以「大制者，以天下之心为心，故无割也」解释不割。","【读法】官长是古代职官之长，长读 zhǎng；圣人用之也有从用朴为长来读的取径。本页循所据注的立官长解释，不将不割读成取消一切分工。"]}],s=[{id:"zhi",term:"知",sense:2,pinyin:"zhī"},{id:"xiong",term:"雄",sense:1},{id:"ci",term:"雌",sense:2},{id:"xi",term:"溪",sense:1},{id:"shi",term:"式",sense:1},{id:"te",term:"忒",sense:1},{id:"wuji",term:"无极",sense:1},{id:"rong",term:"荣",sense:1},{id:"ru",term:"辱",sense:1},{id:"pu",term:"朴",sense:2},{id:"qi",term:"器",sense:1},{id:"guanzhang",term:"官长",sense:1},{id:"dazhi",term:"大制",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十八章",tabindex:"-1"},[o("道德经第二十八章 "),a("a",{class:"header-anchor",href:"#道德经第二十八章","aria-label":'Permalink to "道德经第二十八章"'},"​")],-1)),r(i,{title:"知其一面而守其另一面，怎样回到朴",summary:"雄雌、白黑、荣辱三组知与守，分别接溪、式、谷及三种复归；末段由朴到器、由分殊到官长，再以大制不割收束。",points:[{label:"先读",text:"按知、守、为、复归的次序读三组排句，避免只摘守雌或守辱。"},{label:"再辨",text:"婴儿、无极、朴分别说复归的不同面貌，不强合为一个具体状态。"},{label:"后看",text:"朴散为器已经承认分殊，关键在分工之后怎样不割裂整体。"}],hint:"雌在本章循王弼居后义；朴循真义。官长的长读 zhǎng，忒读 tè。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:n,glossary:s}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"知其雄，守其雌，为天下溪。",tone:"知与守",guide:"知并没有被取消；守选择不以先强自居，溪谷再说明何以能容。"},{text:"为天下谷，常德乃足，复归于朴。",tone:"返后与全德",guide:"三组复归到此汇成朴，为下文从整体到分殊作准备。"},{text:"朴散则为器，圣人用之，则为官长，故大制不割。",tone:"分殊与整体",guide:"承认器与职任的不同，同时追问治理是否割裂了整体所需。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=u('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-三组知守为什么反复说复归" tabindex="-1">象：三组知守为什么反复说复归？ <a class="header-anchor" href="#象-三组知守为什么反复说复归" aria-label="Permalink to &quot;象：三组知守为什么反复说复归？&quot;">​</a></h3><p>每组都先承认人知道在先、显明、荣耀的一面，再选择守住另一面，最后从溪、式、谷回到婴儿、无极、朴。反复不是简单重复，而是在不同对照中说明不被强显荣名占满。</p><h3 id="理-朴既然可贵-为什么还要散而为器" tabindex="-1">理：朴既然可贵，为什么还要散而为器？ <a class="header-anchor" href="#理-朴既然可贵-为什么还要散而为器" aria-label="Permalink to &quot;理：朴既然可贵，为什么还要散而为器？&quot;">​</a></h3><p>末段没有否认分殊和用途的产生。王弼把它连到百行、殊类与官长，显示整体展开为职任之后，仍需使分工不割裂天下之心，故以不割收束。</p><h3 id="用-守雌、守黑、守辱是否要求永远退后" tabindex="-1">用：守雌、守黑、守辱是否要求永远退后？ <a class="header-anchor" href="#用-守雌、守黑、守辱是否要求永远退后" aria-label="Permalink to &quot;用：守雌、守黑、守辱是否要求永远退后？&quot;">​</a></h3><p>本章的守与知相配，不是失去行动能力后的被迫退缩。现代读者可借此反省争先、显耀与逐荣，同时仍按处境承担责任、提出事实与维护必要边界。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>分工时保留共同目的。</strong> 把任务分成不同岗位之后，仍要让信息、责任与最终目标相互接通。否则器越精细，整体越可能被割裂；这属于由古文引出的现代联想。</p><p><strong>有能力，也给承接留位置。</strong> 知道怎样领先，并不意味着每次都必须先发言、先定调。适时听取他人的条件与判断，有助于形成能容纳的合作位置。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：当我强调分工、效率或自己的专业时，是否还能看见共同目的与他人的处境？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「溪」，所据 HFL 录文作「谿」；三组知守及三组复归完整保留。</li><li>雌另设居后语境义，朴另设王弼真义；知读 zhī，不误用通智的 zhì。无极只按本章不可穷理解。</li><li>「圣人用之，则为官长」本页循王弼因其分散而立官长解释，并交代另一取径；大制不割不等于拒绝分工。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，006b–007a</a>。</p>',15))])}}});export{_ as __pageData,k as default};
